      map['linked_stock_item_id'] = Variable<int>(linkedStockItemId);
    }
    if (!nullToAbsent || linkedStockUnitId != null) {
      map['linked_stock_unit_id'] = Variable<int>(linkedStockUnitId);
    }
    if (!nullToAbsent || linkedStockSku != null) {
