class Loan extends DataClass implements Insertable<Loan> {
  final int id;
  final DateTime createdAt;
  final DateTime? updatedAt;
  final String loanNo;
  final int customerId;
  final String itemDesc;
  final double grossWeight;
  final double loanAmount;
  final double interestRate;
  final DateTime startDate;
  final String status;
  const Loan(
      {required this.id,
      required this.createdAt,
      this.updatedAt,
      required this.loanNo,
      required this.customerId,
      required this.itemDesc,
      required this.grossWeight,
      required this.loanAmount,
      required this.interestRate,
      required this.startDate,
      required this.status});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    map['loan_no'] = Variable<String>(loanNo);
    map['customer_id'] = Variable<int>(customerId);
    map['item_desc'] = Variable<String>(itemDesc);
    map['gross_weight'] = Variable<double>(grossWeight);
    map['loan_amount'] = Variable<double>(loanAmount);
    map['interest_rate'] = Variable<double>(interestRate);
    map['start_date'] = Variable<DateTime>(startDate);
    map['status'] = Variable<String>(status);
    return map;
  }

  LoansCompanion toCompanion(bool nullToAbsent) {
    return LoansCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: updatedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(updatedAt),
      loanNo: Value(loanNo),
      customerId: Value(customerId),
      itemDesc: Value(itemDesc),
      grossWeight: Value(grossWeight),
      loanAmount: Value(loanAmount),
      interestRate: Value(interestRate),
      startDate: Value(startDate),
      status: Value(status),
    );
  }

  factory Loan.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Loan(
      id: serializer.fromJson<int>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime?>(json['updatedAt']),
      loanNo: serializer.fromJson<String>(json['loanNo']),
      customerId: serializer.fromJson<int>(json['customerId']),
      itemDesc: serializer.fromJson<String>(json['itemDesc']),
      grossWeight: serializer.fromJson<double>(json['grossWeight']),
      loanAmount: serializer.fromJson<double>(json['loanAmount']),
      interestRate: serializer.fromJson<double>(json['interestRate']),
      startDate: serializer.fromJson<DateTime>(json['startDate']),
      status: serializer.fromJson<String>(json['status']),
