class CashTransaction extends DataClass implements Insertable<CashTransaction> {
  final int id;
  final DateTime createdAt;
  final DateTime? updatedAt;

  /// Human-readable ID: TXN-2025-0001
  final String txnId;

  /// Date & time of the transaction
  final DateTime txnDate;

  /// 'INCOME' or 'EXPENSE'
  final String type;

  /// Income:  SALE, ADVANCE, ORDER_DELIVERY, GIRVI_RETURN,
  ///          LOAN_RECEIVED, INTEREST_RECEIVED, MISC_INCOME, OTHER_INCOME
  /// Expense: SHOP_RENT, STAFF_SALARY, ELECTRICITY, PURCHASE_PAYMENT,
  ///          GIRVI_GIVEN, MAINTENANCE, ADVERTISING, TRANSPORT,
  ///          BANK_CHARGES, GOVT_FEES, MISC_EXPENSE, OTHER_EXPENSE
  final String category;

  /// Free-text label entered by user when category is OTHER_INCOME / OTHER_EXPENSE.
  /// e.g. "Temple Donation", "Emergency Medical", "Tool Purchase"
  final String? customLabel;

  /// Always positive — direction is determined by [type]
  final double amount;

  /// CASH | UPI | CARD | BANK | CHEQUE
  final String paymentMode;

  /// Optional free-text description / note
  final String? description;

  /// ID of the source record (Bill.billNo, SalesOrder.id, etc.)
  final String? referenceId;

  /// 'BILL' | 'ORDER' | 'MANUAL'
  final String? referenceType;

  /// Customer / supplier / party name for quick display
  final String? partyName;

  /// true = auto-created from POS/Booking; false = manually entered
  final bool isAutoGenerated;

  /// true = soft-deleted (never hard-delete financial records)
  final bool isVoided;

  /// Reason provided when voiding
  final String? voidReason;
  const CashTransaction(
      {required this.id,
      required this.createdAt,
      this.updatedAt,
      required this.txnId,
      required this.txnDate,
      required this.type,
      required this.category,
      this.customLabel,
      required this.amount,
      required this.paymentMode,
      this.description,
      this.referenceId,
      this.referenceType,
      this.partyName,
      required this.isAutoGenerated,
      required this.isVoided,
      this.voidReason});
