class GirviLoan extends DataClass implements Insertable<GirviLoan> {
  final int id;
  final DateTime createdAt;
  final DateTime? updatedAt;

  /// Unique ticket number e.g. GRV/2024/00001
  final String ticketNo;
  final int customerId;

  /// Free-text description e.g. "Gold Necklace with pendant"
  final String itemDescription;

  /// Count of items in this girvi
  final int itemCount;

  /// HUID / hallmark certificate number when available
  final String? huidNumber;

  /// Local path of pledged item photo captured at ticket time
  final String? itemPhotoPath;

  /// Gold | Silver | Diamond | Platinum | Mixed | Other
  final String metalType;

  /// 24K | 22K | 18K | 14K | 925 | 999 | Other
  final String metalPurity;

  /// Total gross weight in grams
  final double grossWeight;

  /// Stone/bead/non-metal deduction in grams
  final double stoneWeight;

  /// Net metal weight = gross - stone (computed & stored for speed)
  final double netWeight;

  /// Rate per gram at time of loan (₹/g)
  final double ratePerGram;

  /// Total market value of items (netWeight × ratePerGram)
  final double totalValue;

  /// LTV % = loanAmount / totalValue × 100 (stored for reporting)
  final double ltvPercent;

  /// Principal loan amount disbursed to customer (₹)
  final double loanAmount;

  /// Monthly interest rate in % (e.g. 2.0 = 2% per month)
  final double interestRate;

  /// Agreed loan duration in months
  final int durationMonths;

  /// How the customer received the loan money
  /// Cash | UPI | NEFT | Bank Transfer | Cheque
  final String disbursementMode;

  /// Whether a customer-facing loan invoice was generated at creation
  final bool invoiceGenerated;

  /// Date loan was created/started
  final DateTime startDate;

  /// Maturity date = startDate + durationMonths (stored for alerts)
  final DateTime? maturityDate;

  /// Actual date of release / redemption
  final DateTime? releaseDate;

  /// Date of last interest payment
  final DateTime? lastInterestPaidDate;

  /// Aadhaar | PAN | Voter ID | Passport | Driving License | Other
  final String? idProofType;
  final String? idProofNumber;

  /// Path to scanned ID proof document
  final String? idProofImagePath;

  /// ACTIVE | RELEASED | OVERDUE | AUCTIONED | PARTIAL_RELEASE |
  /// READY_FOR_DELIVERY
  final String status;
  final String? notes;

  /// Principal outstanding at release
  final double? releasePrincipal;

  /// Total interest charged at release
  final double? releaseInterest;

  /// Penalty (if any overdue charges) at release
  final double? releasePenalty;

  /// Total approved discount / waiver across release settlement entries.
  final double? releaseDiscount;

  /// Total amount collected at release
  final double? releaseTotalAmount;

  /// Payment mode used at release
  final String? releasePaymentMode;

  /// Remarks at time of release
  final String? releaseNotes;

  /// Who processed the release (staff name / ID)
  final String? releasedBy;

  /// Customer's promised pickup date after partial/full settlement.
  final DateTime? expectedDeliveryDate;

  /// Actual item handover timestamp. Null means item is still in shop custody.
  final DateTime? deliveredAt;
  const GirviLoan(
      {required this.id,
      required this.createdAt,
      this.updatedAt,
      required this.ticketNo,
      required this.customerId,
      required this.itemDescription,
      required this.itemCount,
      this.huidNumber,
      this.itemPhotoPath,
      required this.metalType,
      required this.metalPurity,
      required this.grossWeight,
      required this.stoneWeight,
      required this.netWeight,
      required this.ratePerGram,
      required this.totalValue,
      required this.ltvPercent,
      required this.loanAmount,
      required this.interestRate,
      required this.durationMonths,
      required this.disbursementMode,
      required this.invoiceGenerated,
      required this.startDate,
      this.maturityDate,
      this.releaseDate,
      this.lastInterestPaidDate,
      this.idProofType,
      this.idProofNumber,
      this.idProofImagePath,
      required this.status,
      this.notes,
      this.releasePrincipal,
      this.releaseInterest,
      this.releasePenalty,
      this.releaseDiscount,
      this.releaseTotalAmount,
      this.releasePaymentMode,
      this.releaseNotes,
      this.releasedBy,
      this.expectedDeliveryDate,
      this.deliveredAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    map['ticket_no'] = Variable<String>(ticketNo);
    map['customer_id'] = Variable<int>(customerId);
    map['item_description'] = Variable<String>(itemDescription);
    map['item_count'] = Variable<int>(itemCount);
    if (!nullToAbsent || huidNumber != null) {
      map['huid_number'] = Variable<String>(huidNumber);
    }
    if (!nullToAbsent || itemPhotoPath != null) {
      map['item_photo_path'] = Variable<String>(itemPhotoPath);
    }
    map['metal_type'] = Variable<String>(metalType);
    map['metal_purity'] = Variable<String>(metalPurity);
    map['gross_weight'] = Variable<double>(grossWeight);
    map['stone_weight'] = Variable<double>(stoneWeight);
    map['net_weight'] = Variable<double>(netWeight);
    map['rate_per_gram'] = Variable<double>(ratePerGram);
    map['total_value'] = Variable<double>(totalValue);
    map['ltv_percent'] = Variable<double>(ltvPercent);
    map['loan_amount'] = Variable<double>(loanAmount);
    map['interest_rate'] = Variable<double>(interestRate);
    map['duration_months'] = Variable<int>(durationMonths);
    map['disbursement_mode'] = Variable<String>(disbursementMode);
    map['invoice_generated'] = Variable<bool>(invoiceGenerated);
    map['start_date'] = Variable<DateTime>(startDate);
    if (!nullToAbsent || maturityDate != null) {
      map['maturity_date'] = Variable<DateTime>(maturityDate);
    }
    if (!nullToAbsent || releaseDate != null) {
      map['release_date'] = Variable<DateTime>(releaseDate);
    }
    if (!nullToAbsent || lastInterestPaidDate != null) {
      map['last_interest_paid_date'] = Variable<DateTime>(lastInterestPaidDate);
    }
    if (!nullToAbsent || idProofType != null) {
      map['id_proof_type'] = Variable<String>(idProofType);
    }
    if (!nullToAbsent || idProofNumber != null) {
      map['id_proof_number'] = Variable<String>(idProofNumber);
    }
    if (!nullToAbsent || idProofImagePath != null) {
      map['id_proof_image_path'] = Variable<String>(idProofImagePath);
    }
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || releasePrincipal != null) {
      map['release_principal'] = Variable<double>(releasePrincipal);
    }
    if (!nullToAbsent || releaseInterest != null) {
      map['release_interest'] = Variable<double>(releaseInterest);
    }
    if (!nullToAbsent || releasePenalty != null) {
      map['release_penalty'] = Variable<double>(releasePenalty);
    }
    if (!nullToAbsent || releaseDiscount != null) {
      map['release_discount'] = Variable<double>(releaseDiscount);
    }
    if (!nullToAbsent || releaseTotalAmount != null) {
      map['release_total_amount'] = Variable<double>(releaseTotalAmount);
    }
    if (!nullToAbsent || releasePaymentMode != null) {
      map['release_payment_mode'] = Variable<String>(releasePaymentMode);
    }
    if (!nullToAbsent || releaseNotes != null) {
      map['release_notes'] = Variable<String>(releaseNotes);
    }
    if (!nullToAbsent || releasedBy != null) {
      map['released_by'] = Variable<String>(releasedBy);
    }
    if (!nullToAbsent || expectedDeliveryDate != null) {
      map['expected_delivery_date'] = Variable<DateTime>(expectedDeliveryDate);
    }
    if (!nullToAbsent || deliveredAt != null) {
      map['delivered_at'] = Variable<DateTime>(deliveredAt);
    }
    return map;
  }

